/**
 * EPS HMAC-SHA512 — tests against fixtures generated by Node's native
 * `crypto.createHmac('sha512', key).update(value).digest('base64')` so
 * any future bump of @noble/hashes that quietly changes output
 * behaviour is caught immediately. This is the load-bearing test
 * alongside the @noble/hashes 1.8.0 → 2.2.0 deferred-bump plan
 * (decisions.md 2026-05-24 — "@noble/hashes deferred to post-Days-24-
 * 25-EPS-truth-gate"). When #72 reopens, this file is the regression
 * fixture that confirms the v2 output is byte-identical to v1.
 *
 * Fixtures were regenerated at Day 36 when the encoding flipped from
 * hex → Base64 (decisions.md "EPS x-hash wire format Base64 not hex"
 * 2026-05-26). The hex regression vectors are no longer canonical;
 * Base64 is what EPS accepts.
 */

import { describe, expect, it } from 'vitest'

import { signEpsField } from './hash.js'

describe('signEpsField (HMAC-SHA512 → Base64)', () => {
  it('signs a typical userName per §11.4 GetToken mechanism', () => {
    // Vector generated via Node crypto:
    //   createHmac('sha512', 'secret-key-123').update('eventpulse').digest('base64')
    expect(signEpsField('eventpulse', 'secret-key-123')).toBe(
      'BUyqAOj7gK16N/3jSGOrJcuCam1CFyZ7Mn6K+zjj+11WG9T3ddFiu5wvI1hIXKLcibQY6a+Utl9LSNL91IFhwA==',
    )
  })

  it('signs a typical merchantTransactionId per §11.4 InitializeEPS mechanism', () => {
    expect(signEpsField('TXN-1234567890', 'hash-key')).toBe(
      'KYLG4WsSCE8+F/ZAM7v4fv+jixtU//uRJr6mXmKD9OO46Xl8JeqvlxrTmAhCs4QkJyz0KLf7j9meFIPDiVklWw==',
    )
  })

  it('signs the empty string deterministically', () => {
    // Edge case: empty value with a non-empty key. EPS shouldn't send
    // this, but the signer's behaviour on empty input is part of the
    // contract.
    expect(signEpsField('', 'k')).toBe(
      'iTzL9dCzNfzab2JeSlkFWjZNdaklFYlCh1B4LBFoMKGvRV7+EJTBkB0Oj9W+tt9kxtX+HG8Jvm70f7OYcmDN2A==',
    )
  })

  it('handles UTF-8 multi-byte values correctly', () => {
    // Bangla input — confirms TextEncoder UTF-8 encoding matches what
    // Node's crypto sees natively. EPS values are typically ASCII, but
    // a buyer-name in a future endpoint signing path could carry
    // Unicode; this pins encoding behaviour.
    expect(signEpsField('আমিনুর', 'k')).toBe(
      'WK+A2Xa8oh5ISknyfJ446zGJhxzBWns1PcL1QeFQin8V8vXmCmkvUegWeng0+tOh8oHP2C0omUsv/0dyrEQ5Pg==',
    )
  })

  it('output is always Base64 with `==` padding (EPS rejects hex)', () => {
    // SHA-512's 64-byte output Base64-encodes to exactly 88 chars
    // ending in `==`. Pin both the alphabet (standard, not URL-safe)
    // and the length so a quiet drift back to hex would fail loudly.
    const out = signEpsField('anything', 'key')
    expect(out).toHaveLength(88)
    expect(out).toMatch(/^[A-Za-z0-9+/]{86}==$/)
  })

  it('is deterministic — same input → bit-identical output', () => {
    const a = signEpsField('input', 'key')
    const b = signEpsField('input', 'key')
    expect(a).toBe(b)
  })

  it('different keys produce different outputs (HMAC, not plain hash)', () => {
    expect(signEpsField('input', 'key-a')).not.toBe(signEpsField('input', 'key-b'))
  })

  it('different values produce different outputs', () => {
    expect(signEpsField('value-a', 'key')).not.toBe(signEpsField('value-b', 'key'))
  })

  describe('input validation', () => {
    it('rejects non-string value', () => {
      // @ts-expect-error: deliberate type misuse
      expect(() => signEpsField(123, 'key')).toThrow(TypeError)
      // @ts-expect-error
      expect(() => signEpsField(null, 'key')).toThrow(TypeError)
      // @ts-expect-error
      expect(() => signEpsField(undefined, 'key')).toThrow(TypeError)
    })

    it('rejects non-string or empty key', () => {
      // @ts-expect-error
      expect(() => signEpsField('value', 123)).toThrow(TypeError)
      expect(() => signEpsField('value', '')).toThrow(TypeError)
      // @ts-expect-error
      expect(() => signEpsField('value', null)).toThrow(TypeError)
    })
  })
})
